create table emk_app.emk_log (
    log_id      number generated always as identity not null enable,
    log_level   varchar2(10 char) not null enable,
    module      varchar2(200 char) not null enable,
    message     varchar2(1000 char) not null enable,
    context     json,
    error_stack clob,
    created_at  timestamp(6) with time zone default on null systimestamp not null enable,
    created_by  varchar2(255 char) default on null coalesce(
        sys_context('APEX$SESSION', 'APP_USER'),
        sys_context('USERENV', 'PROXY_USER'),
        sys_context('USERENV', 'SESSION_USER')
    ) not null enable,
    created_on  date generated always as ( cast(sys_extract_utc(created_at) as date) ) virtual
)
    partition by range (
        created_on
    ) interval ( numtoyminterval(1, 'MONTH') ) ( partition p_initial
        values less than ( to_date(' 2026-01-01 00:00:00', 'SYYYY-MM-DD HH24:MI:SS', 'NLS_CALENDAR=GREGORIAN') )
    );

alter table emk_app.emk_log
    add constraint emk_log_level_ck
        check ( log_level in ( 'DEBUG', 'INFO', 'WARN', 'ERROR' ) ) enable;

alter table emk_app.emk_log
    add constraint emk_log_pk primary key ( log_id )
        using index enable;


